```python
import json

# A literal is (proposition, polarity).
def pos(p):
    return (p, True)

def neg(p):
    return (p, False)

facts = {
    pos("badger_has_couch"),
    pos("gadwall_has_blue_card"),
    pos("mouse_refuses_stork"),
    pos("stork_in_Ankara"),
}
checks = {
    "gadwall_friend_count": 6 + 1,
    "blue_in_France_flag": "blue" in {"blue", "white", "red"},
    "badger_has_seating": "couch" in {"couch", "chair", "bench"},
    "matching_name_initials": "Luna"[0] == "Tango"[0],
    "vampire_age_days_lower_bound": 3 * 365,
}

if checks["gadwall_friend_count"] < 6:
    facts.add(pos("gadwall_fewer_than_6_friends"))
if checks["blue_in_France_flag"]:
    facts.add(pos("gadwall_card_color_in_France_flag"))
if checks["badger_has_seating"]:
    facts.add(pos("badger_has_seating"))
if checks["matching_name_initials"]:
    facts.add(pos("matching_name_initials"))
if checks["vampire_age_days_lower_bound"] > 48:
    facts.add(pos("vampire_older_than_48_days"))

rules = []

def rule(number, antecedents, conclusion):
    rules.append((number, frozenset(antecedents), conclusion))

rule(1, [pos("gadwall_fewer_than_6_friends")], pos("gadwall_builds_power_plant"))
rule(2, [pos("stork_in_Canada")], neg("stork_surrenders"))
rule(3, [neg("badger_trades")], neg("mannikin_unites"))
rule(4, [pos("gadwall_card_color_in_France_flag")], pos("gadwall_builds_power_plant"))
rule(5, [neg("gadwall_hugs"), neg("mannikin_unites")], neg("pelikan_swears"))
rule(6, [pos("vampire_older_than_48_days")], pos("vampire_takes_over"))
rule(7, [pos("badger_has_seating")], neg("badger_trades"))
rule(8, [pos("stork_surrenders")], pos("pelikan_hides"))
rule(10, [pos("matching_name_initials")], neg("badger_trades"))
rule(11, [pos("vampire_takes_over")], neg("pelikan_hides"))
rule(13, [pos("mouse_refuses_stork")], pos("stork_surrenders"))

creatures = [
    "badger", "gadwall", "german_shepherd", "otter", "mouse", "stork",
    "shark", "vampire", "seahorse", "mannikin", "pelikan", "lizard",
    "fangtooth", "fish",
]
for creature in creatures:
    rule(9, [pos(creature + "_creates_castle")], pos(creature + "_hugs"))
    rule(12, [pos(creature + "_builds_power_plant")], neg(creature + "_hugs"))

preferred = {(13, 2), (8, 11), (9, 12)}

state = set(facts)
seen = set()
settled = False
for _ in range(100):
    key = frozenset(state)
    if key in seen:
        break
    seen.add(key)

    applicable = [
        (number, conclusion)
        for number, antecedents, conclusion in rules
        if antecedents <= state
    ]
    accepted = [
        (number, conclusion)
        for number, conclusion in applicable
        if not any(
            other_conclusion == (conclusion[0], not conclusion[1])
            and (other_number, number) in preferred
            for other_number, other_conclusion in applicable
        )
    ]
    next_state = facts | {conclusion for _, conclusion in accepted}
    if next_state == state:
        settled = True
        break
    state = next_state

if not settled:
    print("UNSUPPORTED")
else:
    positive = pos("pelikan_swears") in state
    negative = neg("pelikan_swears") in state
    answer = (
        "proved" if positive and not negative else
        "disproved" if negative and not positive else
        "unknown" if not positive and not negative else None
    )
    if answer is None:
        print("UNSUPPORTED")
    else:
        relevant = {
            "gadwall_builds_power_plant", "gadwall_hugs",
            "badger_trades", "mannikin_unites", "pelikan_swears",
        }
        evidence = [
            {
                "rule": number,
                "conclusion": ("" if polarity else "not ") + proposition,
            }
            for number, (proposition, polarity) in accepted
            if proposition in relevant
        ]
        print(json.dumps({
            "final_answer": answer,
            "evidence": {
                "blue_in_France_flag": checks["blue_in_France_flag"],
                "couch_is_seating": checks["badger_has_seating"],
                "derivations": evidence,
                "positive_support": positive,
                "negative_support": negative,
            },
        }, separators=(",", ":")))
